            if ($this->isNew() && null === $this->collWorkflowInstances) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getWorkflowInstances());
            }
            $query = WorkflowInstanceQuery::create(null, $criteria);
            if ($distinct) {
