    }

    /**
     * @param	WorkflowInstance $workflowInstance The workflowInstance object to add.
     */
    protected function doAddWorkflowInstance($workflowInstance)
    {
        $this->collWorkflowInstances[]= $workflowInstance;
        $workflowInstance->setBpmnSimulation($this);
    }

    /**
     * @param	WorkflowInstance $workflowInstance The workflowInstance object to remove.
     * @return BpmnSimulation The current object (for fluent API support)
     */
    public function removeWorkflowInstance($workflowInstance)
    {
        if ($this->getWorkflowInstances()->contains($workflowInstance)) {
            $this->collWorkflowInstances->remove($this->collWorkflowInstances->search($workflowInstance));
            if (null === $this->workflowInstancesScheduledForDeletion) {
                $this->workflowInstancesScheduledForDeletion = clone $this->collWorkflowInstances;
                $this->workflowInstancesScheduledForDeletion->clear();
            }
            $this->workflowInstancesScheduledForDeletion[]= $workflowInstance;
            $workflowInstance->setBpmnSimulation(null);
        }

        return $this;
    }


